?><!doctype html><html><head><title>Street Intelligence</title><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;background:#f5f3ef;font-family:Arial;color:#111}.hero{background:#111827;color:white;padding:30px}.hero h1{color:#c8a96e}.wrap{max-width:1800px;margin:auto;padding:20px}.panel{background:white;border-radius:18px;overflow:hidden}.btn{background:#c8a96e;padding:10px 14px;border-radius:10px;font-weight:900;text-decoration:none;color:#111;margin:4px;display:inline-block}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}th{background:#faf9f6;color:#777;font-size:11px}.score{font-size:30px;color:#c8a96e;font-weight:900}</style></head><body><?php $rows=sbget('street_intelligence?select=*&order=street_score.desc,updated_at.desc&limit=500'); ?><section class='hero'><h1>Street Intelligence</h1><p>Jessica scores opportunity patterns by street.</p></section><main class='wrap'><p><a class='btn' target='_blank' href='/lead-engine/build-street-intelligence.php?key=<?=h($key)?>'>Refresh Street Scores</a></p><section class='panel'><table><tr><th>Score</th><th>Street</th><th>Owner Signals</th><th>Tax</th><th>Jessica Notes</th><th>Action</th></tr><?php foreach($rows['data'] as $s):?><tr><td><div class='score'><?=h($s['street_score'])?></div></td><td><strong><?=h($s['street_name'])?></strong><br><?=h($s['town'])?></td><td>Owners <?=h($s['owner_count'])?><br>Trusts <?=h($s['trust_count'])?> | Estates <?=h($s['estate_count'])?> | LLC <?=h($s['llc_count'])?></td><td>Avg $<?=h($s['avg_tax'])?><br>Total $<?=h($s['total_tax'])?></td><td><?=h($s['jessica_notes'])?></td><td><?=h($s['recommended_action'])?></td></tr><?php endforeach;?></table></section></main></body></html>